    /** TD-2: sharing on, friends, and a week of meals, water, steps, UREC visits and points. */
    private void seedDemoHistory(Long alice, Long bob) {
        for (Long id : new Long[]{alice, bob}) {
            ConsentSettings c = consents.findById(id).orElseGet(() -> new ConsentSettings(id));
            c.set(true, true, true, true);
            consents.save(c);
        }
        Instant now = Instant.now();
        LocalDate today = clock.today();
        friendships.save(new Friendship(alice, bob, clock.startOf(today.minusDays(HISTORY_DAYS + 1))));
        // TD-6 §5: load the UTD Dining items (stub feed) so the demo meals point at real dining_items rows.
        Map<String, DiningItem> dining = new HashMap<>();
        for (String loc : diningMenu.locations()) {
            for (DiningItem d : diningMenu.fetchItems(loc)) dining.put(d.getLocation() + "|" + d.getName(), d);
        }
        seedWeek(alice, "DEMO-WATCH-ALICE", ALICE_WEEK, today, now, dining);
        seedWeek(bob, "DEMO-WATCH-BOB", BOB_WEEK, today, now, dining);
        log.info("Seeded TD-2 demo data: alice and bob are friends, share all stats, {} days of history", HISTORY_DAYS + 1);
    }

    private void seedWeek(Long student, String deviceId, Week w, LocalDate today, Instant now,
                          Map<String, DiningItem> dining) {
        SmartDevice device = devices.save(new SmartDevice(deviceId, "watch", "simulated"));
        DeviceLink link = new DeviceLink(student, device);
        link.pair();
        links.save(link);

        PointAccount account = pointAccounts.findById(student).orElseGet(() -> new PointAccount(student));
        for (int i = 0; i <= HISTORY_DAYS; i++) {
            LocalDate day = today.minusDays(HISTORY_DAYS - i);
            Instant start = clock.startOf(day);

            int[] hours = {8, 12, 18};
            for (int m = 0; m < 3; m++) {
                String[] plate = w.meals()[i][m];
                for (int k = 0; k < plate.length; k++) {
                    Instant t = at(start, hours[m], k * 2, now);
                    if (t == null) continue;
                    DiningItem d = dining.get(plate[k]);
                    if (d == null) throw new IllegalStateException("Demo meal item not in the UTD Dining feed: " + plate[k]);
                    // TD-6 §3: unpublished macros stay null, exactly as the dining item has them.
                    meals.save(new MealEntry(student, d.getName(), d.getCalories(), d.getProteinG(), d.getCarbsG(),
                            d.getFatG(), MealSource.DINING_MENU, d.getItemId(), t));
                }
            }
            for (int r = 0; r < w.refillsOf500ml()[i]; r++) {
                Instant t = at(start, 9 + r * 3, 0, now);
                if (t != null) water.save(new WaterEntry(student, 0.5, t));
            }
            int steps = w.steps()[i];
            int[] parts = {steps * 30 / 100, steps * 45 / 100, steps - steps * 30 / 100 - steps * 45 / 100};
            int[] syncHours = {10, 15, 20};
            int synced = 0;
            for (int p = 0; p < 3; p++) {
                Instant t = at(start, syncHours[p], 0, now);
                if (t == null) continue;
                activity.save(new ActivityRecord(student, device.getId(), parts[p], 70 + p * 12, t));
                synced += parts[p];
            }
            if (synced >= 10_000) award(account, student, PointsService.STEP_GOAL, at(start, 20, 1, now));
            if (w.urecVisit()[i]) {
                Instant t = at(start, 7, 30, now);
                if (t != null) {
                    visits.save(new RecVisit(student, UREC_READER, t));
                    award(account, student, PointsService.VISIT, t);
                }
            }
        }
        pointAccounts.save(account);
    }

    private void award(PointAccount account, Long student, String reason, Instant t) {
        if (t == null) return;
        int amount = PointsService.pointsFor(reason);
        account.addPoints(amount);
        pointTx.save(new PointTransaction(student, amount, reason, t));
    }

    /** start-of-day + h:m, or null when that time is still in the future (today's history stops at "now"). */
    private static Instant at(Instant startOfDay, int hour, int minute, Instant now) {
        Instant t = startOfDay.plus(Duration.ofHours(hour)).plus(Duration.ofMinutes(minute));
        return t.isAfter(now) ? null : t;
    }
}
package cometfit;

import static org.assertj.core.api.Assertions.assertThat;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;

import org.junit.jupiter.api.Test;

import com.fasterxml.jackson.databind.JsonNode;

/**
 * TD-2 "Demo accounts share their data": seeded alice and bob start with all sharing on and some activity history,
 * so UC-3 (friends' progress and leaderboard) shows real numbers; real new accounts still share nothing
 * (NFR Ethical / Legislative-Privacy, A-18).
 */
class DemoDataTest extends ApiTestSupport {

    private Account demo(String username, String secret) throws Exception {
        String token = login(username, DemoDataSeeder.DEMO_PASSWORD, secret);
        long id = call(get("/api/auth/me"), token, null, 200).get("userId").asLong();
        return new Account(id, username, secret, token);
    }

    @Test
    void demoStudentsAreFriendsAndShareRealNumbers() throws Exception {
        Account alice = demo("alice", DemoDataSeeder.ALICE_SECRET);
        Account bob = demo("bob", DemoDataSeeder.BOB_SECRET);

        JsonNode consent = GET("/api/social/consent", alice, 200);
        assertThat(consent.get("shareCalories").asBoolean() && consent.get("shareWater").asBoolean()
                && consent.get("shareSteps").asBoolean() && consent.get("shareVisits").asBoolean()).isTrue();

        JsonNode friends = GET("/api/social/friends", alice, 200);
        assertThat(friends.findValuesAsText("username")).contains("bob");

        JsonNode stats = GET("/api/social/friends/" + bob.id() + "/stats", alice, 200);
        assertThat(stats.get("caloriesToday").isNull()).isFalse();
        assertThat(stats.get("waterTodayMl").isNull()).isFalse();
        assertThat(stats.get("stepsToday").isNull()).isFalse();
        assertThat(stats.get("visitsThisWeek").isNull()).isFalse();
        assertThat(stats.get("points").asInt()).isPositive();

        JsonNode board = GET("/api/social/leaderboard", bob, 200);
        assertThat(board.size()).isGreaterThanOrEqualTo(2);
        assertThat(board.findValuesAsText("username")).contains("alice", "bob");

        // "some activity history": visits and points from earlier days
        JsonNode visits = GET("/api/activity/visits", alice, 200);
        assertThat(visits.get("visits").size()).isGreaterThanOrEqualTo(3);
        assertThat(visits.get("balance").asInt()).isPositive();
    }

    /** TD-6 §5: the demo meal history uses real UTD Dining items (spec/06-utd-dining), not placeholder meals. */
    @Test
    void demoMealHistoryUsesRealUtdDiningItems() throws Exception {
        Account alice = demo("alice", DemoDataSeeder.ALICE_SECRET);
        java.time.LocalDate yesterday = java.time.LocalDate.now(java.time.ZoneId.of("America/Chicago")).minusDays(1);
        JsonNode meals = GET("/api/nutrition/meals?date=" + yesterday, alice, 200);
        assertThat(meals.size()).isGreaterThanOrEqualTo(3);
        java.util.Set<String> menuNames = new java.util.HashSet<>();
        for (String loc : Td6UtdDiningTest.LOCATIONS) {
            GET("/api/nutrition/menu?location=" + loc, alice, 200)
                    .forEach(it -> menuNames.add(it.get("name").asText()));
        }
        for (JsonNode m : meals) {
            assertThat(m.get("source").asText()).isEqualTo("DINING_MENU");
            assertThat(m.get("diningItemId").isNull()).isFalse();
            assertThat(menuNames).contains(m.get("foodName").asText());
            assertThat(m.get("foodName").asText()).doesNotContain("(demo)");
        }
        // bob's history includes calories-only items (macros "not published") on some day of the week
        Account bob = demo("bob", DemoDataSeeder.BOB_SECRET);
        boolean sawNull = false;
        for (int d = 1; d <= DemoDataSeeder.HISTORY_DAYS; d++) {
            for (JsonNode m : GET("/api/nutrition/meals?date=" + yesterday.minusDays(d - 1), bob, 200)) {
                sawNull |= m.get("proteinG").isNull();
            }
        }
        assertThat(sawNull).isTrue();
    }

    @Test
    void realNewAccountsStillShareNothing() throws Exception {
        Account fresh = newStudent("fresh");
        JsonNode consent = GET("/api/social/consent", fresh, 200);
        assertThat(consent.get("shareCalories").asBoolean() || consent.get("shareWater").asBoolean()
                || consent.get("shareSteps").asBoolean() || consent.get("shareVisits").asBoolean()).isFalse();
    }
}
