        this.diningMenu = diningMenu;
        this.accounts = accounts;
        this.users = users;
        this.clock = clock;
        this.consents = consents;
        this.friendships = friendships;
        this.meals = meals;
        this.water = water;
        this.devices = devices;
        this.links = links;
